"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"ظاهر جدید سنگ‌معدن: رگه‌ها کریستال‌های زمردی تراش‌خورده و درخشان روی بازالت سیاه‌اند با جرقه و مه سبز؛ اکسترکتور یک پایه شش‌ضلعی با گنبد لانه‌زنبوری و برج مشبک است که فانوس سبز بالای آن می‌درخشد (نوار و پرچم به رنگ تیم)",
"New in v6.1":"تازه‌های v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"کلاس دلخواه مثل Battlefield (U، اعداد بعد از مرگ): در صورت وجود، دوباره در همان کلاس ظاهر می‌شوی",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"ماشین‌های جنگی از دید اول‌شخص (V — بیرون/کابین)؛ کمک‌هدف‌گیری ملایم — در تنظیمات",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"بیرون آمدن از هسته آسان شد: Space — به سمت چاه، B — کپسول به سطح؛ اثر توانایی‌ها هنگام مرگ بازنشانی می‌شود",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"پیشرفت بی‌پایان: ژنرال‌ها و مارشال ★، سطوح کارنامه، تسلط بر سلاح و ادوات، مدال‌ها، قراردادهای روزانه — صفحه «کارنامه»",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"استراتژی: زوم نرم با چرخ ماوس، آیکون و برچسب بالای واحدها (Alt — همه)، پنل «نیروها / ساختمان‌ها» در سمت چپ",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"‏RMB — حرکت همراه با حمله، دو بار RMB — راهپیمایی با تیراندازی در حرکت؛ دستورهای کم‌کاربرد در «دستورهای بیشتر ▾»؛ بدون دکمه‌های تکراری",
"New in v6":"تازه‌ها در v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"تیراندازی در سطح شوترها: گلوله‌های آنی، تفنگ ۷۲۰ گلوله در دقیقه، مسلسل، پس‌زنی، نشانه‌روی با RMB، خشاب و بارگذاری مجدد با R، نشانگر اصابت",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"گرانش سنگین‌تر، جت‌پک پاسخگو، شیرجه با Z یا دو بار جت‌پک در هوا؛ هنگام تغییر واحد، سلاح دیگر همراهت پرواز نمی‌کند",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"مهندس‌ها: مهندس را انتخاب کن، ساختمان را برگزین، نقشه را بگذار؛ اکسترکتورها روی رگه‌های ماعدن؛ با کلیک روی «ماعدن» درآمد و راه افزایش آن را ببین",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"دکمه‌های خاکستری توضیح می‌دهند چرا و راه‌حل پیشنهاد می‌دهند؛ دکمه‌های بزرگ‌تر، نوار «در حال انجام»، «▶ تسخیر»، Tab تنها کلید تغییر حالت",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"دوربین استراتژی بدون پرش و چرخش، زوم به سمت نشانگر، مینی‌مپ قابل کشیدن",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"ماشین‌های تازه: «شغال» (غارتگر)، «گراد» (راکت‌انداز چندلول با موشک‌های هدایت‌شونده)، خمپاره‌انداز «چکش»؛ گروه «گروه» «زنبور»، «کندو» و «منجنیق» را می‌گیرد",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"استراتژیست دستورها را حفظ می‌کند و صدا را اسپم نمی‌کند؛ نبردها نزدیک تو رخ می‌دهند؛ B — انتقال، Shift+B — به قلب نبرد؛ قطب‌نما، H — کدام هدف",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"آزادی عمل (K) و «تنها عمل می‌کنم» (J)، F2 — پیش‌تنظیم‌ها؛ Esc — توقف و ادامه؛ ذخیره‌سازی: اسلات‌ها، برون‌بری و درون‌ریزی فایل",
"New in v5.3":"تازه‌ها در v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"پرواز: گرانش دور از شهاب‌سنگ قوی‌تر، C در هوا ترمز است، رانش تندتر هدایت می‌کند؛ دیگر در پورتال گیر نمی‌کنی",
"New in v5":"تازه‌ها در v5",
"Endless war by default and battle scale: normal, large, epic":"نبرد بی‌پایان به‌صورت پیش‌فرض و مقیاس نبردها: عادی، بزرگ، حماسی",
"Save and load the battle (autosave every 3 minutes)":"ذخیره و بارگذاری نبرد (و ذخیره خودکار هر ۳ دقیقه)",
"Squadmates with callsigns: portraits, health and live chatter":"هم‌تیمی‌ها با نام رمز: پرتره‌ها، سلامتی و گفت‌وگوهای زنده",
"Fog of war in strategy, friends and foes outlined differently":"مه جنگ در استراتژی، دوست و دشمن با رنگ‌های متفاوت",
"Camera fly-over when switching, portal aurora instead of rings":"پرواز دوربین هنگام تغییر، شفق پورتال به‌جای حلقه‌ها",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"مأموریت‌های فرعی، میان‌بر از آسمان، زیستگاه‌های اولین اکتشاف با آذوقه، کریستال‌ها، یخ دهانه‌ها، طوفان‌های گرد و غبار",
