"Saves live only in this browser on this device (localStorage). Anyone else who downloads the game gets none of your saves. To move a battle to another computer or browser: \"Export to file\" here → \"Import from file\" there. Autosave runs every 3 minutes of battle and when you quit to the menu.":"ذخیره‌ها فقط در همین مرورگر روی همین دستگاه نگهداری می‌شوند (localStorage). اگر کس دیگری بازی را دانلود کند، ذخیره‌های تو را نخواهد داشت. برای انتقال نبرد به رایانه یا مرورگر دیگر: «برون‌بری به فایل» اینجا ← «درون‌ریزی از فایل» آنجا. ذخیره خودکار هر ۳ دقیقه نبرد و هنگام خروج به منو انجام می‌شود.",
