"Branch fully upgraded":"شاخه کامل ارتقا یافته",
"Need {0} ore":"‏{0} سنگ‌معدن لازم است",
"Outpost{0}: {1} ready":"پایگاه پیشرو{0}: {1} آماده شد",
"{0} is online":"‏{0} آماده است",
"The HQ is destroyed":"ستاد نابود شده است",
"The HQ is already building an upgrade":"ستاد همین حالا در حال ساخت یک ارتقاست",
"HQ: {0} ready":"ستاد: {0} آماده شد",
