"Intel: the Swarm HQ got \"{0}\"":"اطلاعات: ستاد «Swarm» «{0}» را گرفت",
"Point {0}: orbit is dropping a pod — a squad{1}":"نقطه {0}: مدار دارد کپسول می‌اندازد — یک دسته{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"کپسول روی نقطه {0}: {1}{2}{3}. مهندس می‌تواند پایگاه پیشرو بسازد (V) و شاخه ارتقا انتخاب کند.",
"HQ radar: every enemy is visible for 6 s":"رادار ستاد: همه دشمنان ۶ ثانیه دیده می‌شوند",
"HQ upgrades":"ارتقاهای ستاد",
"Built":"ساخته شد",
"Building — click to cancel (refund)":"در حال ساخت — کلیک: لغو (بازپرداخت)",
"Outpost upgrades":"ارتقاهای پایگاه پیشرو",
"point":"نقطه",
"Pick a branch — every point gets its own speciality:":"یک شاخه انتخاب کن — هر نقطه تخصص خودش را دارد:",
"Building — click to cancel":"در حال ساخت — کلیک: لغو",
"A builder near the outpost (30 m) does the upgrade.":"مهندس نزدیک پایگاه پیشرو (۳۰ m) ارتقا را می‌سازد.",
"Send a builder":"مهندس بفرست",
"Builders nearby":"مهندس‌های نزدیک",
"{0} is heading to the outpost":"‏{0} به سمت پایگاه پیشرو می‌رود",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"از همان آغاز نبرد کل ارتش در پایگاه توست، از هر نوع یکی: سربازان فرود، توپچی سنگین تک، تک‌تیرانداز، دیده‌بان، پهپاد، «شغال»، «گراد»، «چکش» (و دسته‌های تهاجمی با تانک) — بلافاصله هرکدام را کنترل کن",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"‏«ترتیب دلخواه» کنترل (منوی مکث، روی گوشی ☰): هر کلاس شماره‌ای دارد، 1 در اولویت بالاست؛ ▲▼ آن را تغییر می‌دهند، ✕ یعنی هرگز. پس از مرگ و با X سربازِ نزدیک‌تر به نبرد طبق این ترتیب گرفته می‌شود",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"ربات‌ها دیگر تک‌تیرانداز نیستند: از دور، در حال دویدن، روی دونده‌ها و پشت پناه خطا می‌زنند؛ گلوله‌ها کنارت سوت می‌کشند و به زمین و پناه اطراف می‌خورند. انفجارها زمینت می‌زنند: تکان، زانو زدن، افتادن و برخاستن",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"یک نقطه را بگیر تا کپسولی با دسته و مهندس فرود بیاید. پایگاه پیشرو روی نقطه در یک شاخه ارتقا می‌یابد: دفاع (سنگر مسلسل ← بونکر با توپ ضدتانک)، پشتیبانی (پهپادهای تعمیرکار ← گنبد میدان نیرو)، شناسایی (اسکنر رادیویی ← برج تک‌تیرانداز)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"ستاد هم ارتقا می‌یابد: صفحات زره، برجک‌ها، فرود مداری سریع‌تر، درآمد ۲۵٪+، رادار سراسری، آنتن‌های ارتباطی (+امتیاز فرماندهی). هوش مصنوعی هم همین کار را می‌کند",
"New in v7.0":"جدید در v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"در پایگاه از هر نوع سرباز و ماشین یکی هست: سربازان فرود، تک‌تیرانداز، دیده‌بان، پهپاد، «شغال»، «گراد»، «چکش». هرکدام را انتخاب کن و {0} — پیش از ساختن امتحانشان کن.",
"POSSESS":"کنترل بگیر",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"نقطه {0}: مهندس با کپسول فرود آمد. انتخابش کن و کنار نقطه یک «پایگاه پیشرو»{1} بساز — بعد شاخه ارتقا را انتخاب می‌کنی.",
"OUTPOST":"پایگاه پیشرو",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"پایگاه پیشرو آماده است — انتخابش کن و شاخه را برگزین: ⛨ دفاع (سنگر مسلسل، بونکر ضدتانک)، ✚ پشتیبانی (پهپادهای تعمیرکار، گنبد میدان نیرو) یا ◎ شناسایی (اسکنر، برج تک‌تیرانداز). مهندس نزدیک می‌سازد.",
"UPGRADE":"ارتقا",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"ستاد یک «ابرنقطه» است: انتخابش کن{0} — زره، برجک‌ها، فرود سریع‌تر، درآمد ۲۵٪+، رادار، آنتن‌های ارتباطی.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"‏☰ ← «کنترل»: «ترتیب دلخواه» را روشن کن و تعیین کن بعد از مرگ در چه کسی بروی — شماره 1، 2… ✕ یعنی هرگز.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"‏Esc ← مکث ← «ترتیب دلخواه»: تعیین کن بعد از مرگ و با X در چه کسی بروی — شماره 1، 2… ✕ یعنی هرگز.",
