"The Polygon works in developer mode only":"میدان آزمایش فقط در حالت سازنده کار می‌کند",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"‏⚔ میدان آزمایش: نبردی بی‌پایان در مرکز نقشه با نیروی کمکی. X — کنترل یک سرباز در آنجا",
"Polygon off — its units are back under AI command":"میدان آزمایش خاموش شد — واحدهایش دوباره زیر فرمان هوش مصنوعی‌اند",
