"Voice of hints & curator":"صدای راهنماها و راهنما",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"گوشی: سه حالت جویستیک. فقط چپ — «خودکار» (آهنربای قوی، گلوله‌های ضعیف‌تر). فقط راست — نشانه خودش روشن می‌شود، آهنربای قوی‌تر، دقت بهتر. هر دو — بدون نشانه، آهنربا و دقت کمتر. دکمهٔ 👁 سمت راست — پنهان/بازگرداندن رابط.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"گوشی: استراتژی ساده شد — فقط مهندس و ساختمان‌ها. کارت‌ها سمت چپ (مهندس، ستاد، پادگان…): ضربه — دوربین به آنجا می‌رود، نوار پایین نشان می‌دهد چه بسازی/تولید کنی. «به نبرد» — بالا سمت چپ. ارتش خودش می‌جنگد. استراتژی کامل — تنظیمات ← گوشی.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"تسخیر — دو کلید: «دسته‌ها» و «تجهیزات» (روی گوشی تجهیزات به‌طور پیش‌فرض خاموش است — هوش مصنوعی می‌راندشان). اگر تجهیزات خاموش باشد، E (روی گوشی — دکمهٔ سمت راست) کنار ماشین خودی — پشت توپش بنشین: ماشین خودش می‌رود، تو شلیک می‌کنی. «ترتیب دلخواه کلاس‌ها»ی قدیمی در «پیشرفته» است. هنگام تسخیر، یگان از طریق بی‌سیم جواب می‌دهد.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"راهنماهای هوشمند: راهنماهای پایه بعد از اجرای دوم خودشان خاموش می‌شوند، ولی بازی قابلیتی را که هرگز استفاده نکرده‌ای یادآوری می‌کند. کلیدها: پایه / پیشرفته / نادر، و جداگانه — صدای راهنماها و راهنما.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"رفلکس با کشتن شارژ می‌شود (کشتارهای پیاپی بیشتر شارژ می‌کنند). اعضای دسته عقب ماندند یا مردند — استراتژیست نیروی تازه برایت فرود می‌آورد (گران‌تر از تقویت عادی). گرافیک و صدای v7.2gfx ادغام شد: انفجارهای ابری، دود، آوار، آکوستیک چاه‌ها و دهانه‌ها. تاریخ ساخت حالا واقعی است.",
