"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"کارنامه و ذخیره‌ها تغییر نمی‌کنند. در نبرد همین منو دکمهٔ «🛠 منو» بالا سمت راست است{0}.",
"New developer match":"مسابقهٔ جدید توسعه‌دهنده",
"all unlocked, endless ore, instant build, arsenal":"همه‌چیز باز، سنگ‌معدن بی‌پایان، ساخت فوری، زرادخانه",
"Trainings — all 4":"آموزش‌ها — هر ۴",
"PC and phone (strategy and shooter)":"رایانه و گوشی (استراتژی و تیرانداز)",
"Cinema: split screen":"سینما: صفحه تقسیم‌شده",
"strategist bot left, shooter bot right":"سمت چپ ربات استراتژیست، سمت راست ربات تیرانداز",
"Cinema: everything built":"سینما: همه‌چیز ساخته شد",
"both bases built and upgraded — for footage":"هر دو پایگاه ساخته و ارتقا یافتند — برای فیلم‌برداری",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"حالت سینما — صفحه تقسیم‌شده: سمت چپ ربات استراتژیست (نمای بالا روی پایگاه و ارتش)، سمت راست ربات تیرانداز از دید اول‌شخص. دکمه‌های پایین (و کلیدهای S، P): «صفحه تقسیم‌شده» و «★ همه ساخته شد» — هر دو پایگاه برای فیلم‌برداری ساخته و ارتقا یافتند.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"هسته و تونل‌های درون شهاب‌سنگ دیگر وجود ندارند — شهاب‌سنگ یکپارچه است و نبرد فقط روی سطح جریان دارد.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"گوشی: 👁 رابط را پنهان می‌کند، اما جت‌پک، ⇆، استیک‌ها و نشانگر هدف می‌مانند. «◎ نشانه‌گیری» (فقط انگشت راست) — آهنربای محسوساً قوی‌تر و گسترده‌تر؛ قدرت آهنربا برای هر سه حالت — تنظیمات ← کنترل ← «پیشرفته». پشت توپ خودرو دکمه «پیاده شو» نام دارد.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"آموزش: روی گوشی فقط آموزش‌های گوشی، روی رایانه فقط آموزش‌های رایانه. هر ۴ آموزش در منوی «🛠 توسعه‌دهنده» هستند. حالت توسعه‌دهنده و زرادخانه در یک منو ادغام شده‌اند (در نبرد — «🛠 منو» بالا سمت راست، روی رایانه F8 هم).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"سبک گرافیک «Dendy (8 بیتی)» و «16 بیتی»: تنظیمات ← گرافیک ← «سبک گرافیک» (جزئیات — دکمه ⚙). اگر در ۱۰ ثانیه اول مسابقه FPS زیر ۲۴ باشد، Dendy خودکار روشن می‌شود (زیر ۲۰ و کمتر — پیکسل درشت‌تر، ۱۲۰ خط)؛ نوار بالا با «بازگشت به عادی» گرافیک عادی را برای همیشه برمی‌گرداند. انتخاب خودت در منو همیشه مقدم است.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"مدل‌های سه‌بعدی محیط (خرابه‌ها، ادوات، استحکامات) — فقط مدل‌های با امتیاز خوب، که بر حسب نیاز از اینترنت بارگیری می‌شوند. خاموش کردن: تنظیمات ← گرافیک ← «مدل‌های سه‌بعدی جدید محیط».",
