"Prone / stand up (crawl)":"دمر شدن / برخاستن (خزیدن)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"ساخت‌وساز با سربازان: E (روی گوشی «ورود») کنار ساخت‌وساز خودی — سربازت خودش می‌سازد و هم‌تیمی‌های نزدیک کمک می‌کنند. اگر مهندس‌ها مشغول باشند، استراتژیست از تو کمک می‌خواهد — نشانه «ساخت‌وساز».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"نشانه‌های استراتژیست: استراتژیست ⌖ را روی دسته‌ای از دشمنان نزدیک تو می‌گذارد — ۸ s بعد توپخانه آنجا را می‌زند و موشک‌بارانِ «گراد»ِ خودیِ نزدیک رگبار می‌زنند. حمله توپخانه‌ات از حالت استراتژی هم با پشتیبانی «گراد» همراه است.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"انبارهای مخفی سلاح در کانتینرهای باری و ماهواره‌های سقوط‌کرده (📦 از ۷۰ m دیده می‌شود): E — مسلسل سنگین به مدت ۹۰ s، گلوله آتشزا یا موشک، به‌علاوه نارنجک‌های پر. خزیدن: Ctrl — دمر شدن / برخاستن (پایین‌تر و دقیق‌تر، اما کند).",
"Anonymous statistics":"آمار ناشناس",
