"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"‏«▶ همین حالا بازی کن» — اولین دکمه منو: پروازی کوتاه زیر آسمانِ پورتال — و یکراست به نبرد (رد کردن — هر کلید یا ضربه).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"اصابت‌ها واقعی حس می‌شوند: صدای فلزی و جرقه، نشانه نابودی کنار نشانه‌گیر (سرزنی — زرد)، رگه ×N، لرزش نرم از انفجارها، اسلوموشن در نابودی‌های مهم. لرزش، اسلوموشن و راهنما را می‌شود در تنظیمات خاموش کرد.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"نتیجه مسابقه: زمان، نابودی‌ها، بهترین رگه، ★ بهترین بازیکن و بهترین دسته، کارت مسابقه — «⇪ اشتراک‌گذاری»، PNG یا لینک بازی.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"راهنمای «الان چه کنیم» سمت چپ زیر منابع: دستور استراتژیست، نقطه‌ای برای تصرف، حمله انبوه. ✕ یا F7 — جمع کردن.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"اگر زبانه را ببندی یا کوچک کنی، نبرد خودکار ذخیره می‌شود — در منو «⟲ ادامه».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"نسخه v7.5 در منوی «🕘 نسخه بازی» می‌ماند، اگر نسخه جدید را نپسندیدی. آمار ناشناس (بدون نام و ایمیل) حالا ارسال می‌شود؛ خاموش کردن — در تنظیمات.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"‏«همین حالا بازی کن»، بازخورد اصابت‌ها، نتیجه مسابقه با کارت، راهنمای «چه کنیم»، ذخیره خودکار",
"and older: v7.5, v7.4, milestones v1–v7.0":"و قدیمی‌تر: v7.5، v7.4، نقاط عطف v1–v7.0",
"New in v7.6":"تازه‌های v7.6",
"NEW IN v7.6":"تازه‌های v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"انتخاب جناح پیش از مسابقه: «کنسرسیوم» (پیاده‌نظام سنگین با زره نیرویی، زره و توپخانه) یا «انبوه» (سرعت، دسته‌های پهپاد، شلیک‌های سنگین با اعوجاج). هوش مصنوعی جناح دیگر را بازی می‌کند. انتخاب به خاطر سپرده می‌شود.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"هر جناح وسایل نقلیه و ویژگی‌های ویژه‌ی خودش را دارد: کنسرسیوم — تانک «کرگدن» و «صفحات سرامیتی»، دسته — «دسته پهپاد» و «کوله‌پشتی‌های جت فازی». توازن با مسابقه‌های بات‌ها بررسی شده است.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"دهانه‌های انفجار: توپخانه، موشک‌ها و توپ تانک‌ها در شهاب‌سنگ گودال می‌کنند — می‌شود در آن‌ها راه رفت و رانندگی کرد و پشتشان سنگر گرفت.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"نمای سوم‌شخص برای سرباز (V، به خاطر سپرده می‌شود؛ روی گوشی — کنترل) و دوربین نرم وسایل نقلیه با نشانه‌ای که محل برخورد گلوله را نشان می‌دهد.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"نسخه v7.6 در منوی «🕘 نسخه بازی» می‌ماند، اگر ترجیح دادی.",
