"Anomaly! The air is like glass — a Lens, it bends bullets!":"ناهنجاری! هوا مثل شیشه است — عدسی، گلوله‌ها را خم می‌کند!",
"Everything is warping… a Lens nearby!":"همه‌چیز دارد کج می‌شود… عدسی همین نزدیکی است!",
"Ha! An enemy walked right into the anomaly!":"ها! دشمن مستقیم رفت توی ناهنجاری!",
"Got him! Lure them into anomalies!":"گرفتمش! آن‌ها را به ناهنجاری‌ها بکشان!",
"Beautiful zap! One less tin can.":"چه جرقه قشنگی! یک آهن‌پاره کم شد.",
"The anomaly got me!":"ناهنجاری مرا گرفت!",
"Ow! Don't go in there!":"آخ! نروید آن تو!",
"Discharged! It is dormant now.":"تخلیه‌اش کردم! حالا خاموش است.",
"Clear, the anomaly is discharged.":"پاک است، ناهنجاری تخلیه شد.",
"They say veins hide artifacts. Only first the vein sings…":"می‌گویند در رگ‌ها آرتیفکت پنهان است. فقط اول رگ می‌خواند…",
"Throw a bolt first, then walk. Old habit.":"اول پیچ بنداز، بعد برو. عادت قدیمی.",
"throw a bolt":"پرتاب پیچ",
"📦 Supply drop: landing in 4 seconds":"‏📦 کپسول تدارکات: فرود تا ۴ ثانیه دیگر",
