"Pause: resume, restart, training, graphics, settings, main menu":"توقف: ادامه، دوباره، آموزش، گرافیک، تنظیمات، منوی اصلی",
"Menu: pause, restart, training, graphics, settings":"منو: توقف، دوباره، آموزش، گرافیک، تنظیمات",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"انگشت را حدود ۰٫۳ ثانیه روی زمین نگه دار — گوشی می‌لرزد و حلقه زرد ظاهر می‌شود — و بی‌آنکه رها کنی بکش: کادر ساخته می‌شود. یا دکمه «کادر» سمت راست. ضربه ساده روی دسته هم کار می‌کند.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"برای تمام‌صفحه روی iPhone: «Share» ⬆ ← «Add to Home Screen» — بازی بدون نوارهای Safari باز می‌شود.",
"Open portal-meteor.pages.dev for that.":"برای این کار سایت portal-meteor.pages.dev را باز کن.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"ضربه — انتخاب · ضربه روی زمین — حرکت · نگه‌داشتن — منوی فرمان · نگه‌دار و بکش — کادر · ۲ انگشت — زوم",
"Robo-ninja":"روبو-نینجا",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"قهرمان آدم‌کش: جهش‌های برق‌آسا، کاتانا، شوریکن. خودش از میان مناطق دشمن تله‌پورت می‌کند و روبات‌ها را تکه‌تکه می‌کند. ۱ نفر برای هر طرف.",
"Shadow protocol":"پروتکل «سایه»",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"پژوهش: روبو-نینجا را در پادگان باز می‌کند. کارخانه مکای تکمیل‌شده لازم است.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"قهرمان (۱ نفر برای هر طرف): خودش در مناطق دشمن تله‌پورت می‌کند و روبات‌ها را تکه‌تکه می‌کند؛ می‌توانی کنترلش کنی و دستی بازی کنی.",
"is ready. She works on her own (AUTO) — possess her to play manually":"آماده است. خودکار کار می‌کند (خودکار) — کنترلش کن تا دستی بازی کنی",
"Robo-ninja ready for action":"روبو-نینجا آماده نبرد است",
"⚠ Intel: the enemy has a robo-ninja!":"‏⚠ شناسایی: دشمن روبو-نینجا دارد!",
"Warning! The enemy has a robo-ninja. Stay together":"هشدار! دشمن روبو-نینجا دارد. کنار هم بمانید",
"cyber blinks":"جهش‌های سایبری",
"Too far for a dash — get closer or teleport":"برای جهش دور است — نزدیک‌تر شو یا تله‌پورت کن",
"point ":"نقطه ",
"enemy group":"گروه دشمن",
"order":"فرمان",
"nearby":"نزدیک",
"Zone cleared":"منطقه پاکسازی شد",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"‏⚔ دوئل نینجاها! درست پیش از ضربه بلاک کن تا دفع شود، با جهش جاخالی بده. مراقب جرقه آماده‌شدن حمله باش",
"The two ninjas have met in a duel!":"دو نینجا در دوئل به هم رسیدند!",
"⚔ Duel won! Our ninja prevails":"‏⚔ دوئل برده شد! نینجای ما برتر است",
"⚔ Duel lost…":"‏⚔ دوئل باخته شد…",
"ninja duel":"دوئل نینجا",
"POSTURE BROKEN":"حالت دفاعی شکست",
"Teleport":"تله‌پورت",
"Teleport: aim at the ground (up to 150 m)":"تله‌پورت: نشانه‌گیر را روی زمین ببر (تا ۱۵۰ m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"‏✶ خودکار: خودش در مناطق دشمن می‌پرد و می‌برد. جوی‌استیک / WASD — ۱٫۵ ثانیه مکث",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"‏✶ دستی: ضربه روی دشمن — جهش و برش، کشیدن — ضربه شمشیر، 🛡 — بلاک",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"‏✶ کنترل دستی: کلیک چپ — کاتانا، کلیک راست — بلاک، Shift — جهش، Q — شوریکن، G — تله‌پورت",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"‏✶ نینجا: ضربه روی دشمن — حمله‌ی برق‌آسا و برش، کشیدن سمت راست — ضربه‌ی شمشیر، ● — ضربه، 🛡 — دفاع (به‌موقع = دفع)، ⇑ — جهش، ✦ — شوریکن‌ها، ◎ — تله‌پورت، خودکار — به‌تنهایی",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"‏✶ نینجا: کلیک چپ — کاتانا (نگه‌دار — برش سنگین)، کلیک راست — دفاع (به‌موقع = دفع)، Shift/Z — جهش، Q — شوریکن‌ها، G — تله‌پورت به نشانه‌گیر، پرش در هوا — پرش دوم / دویدن روی دیوار، {0} — خودکار",
