"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"رادیو Portal Meteor: بیش از ۱۰۰ آهنگ از EDMITRY درست داخل بازی — دکمه 📻 (رایانه: کلید 5، [ ] — آهنگ). موسیقی در لحظه پخش می‌شود و بازی را سنگین نمی‌کند؛ صدا و پخش خودکار در تنظیمات، به‌علاوه لینک «در Spotify گوش بده».",
