"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"رادیو Portal Meteor روشن/خاموش ([ ] — آهنگ، Shift+[ ] — صدا)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"‏📻 سمت راست — رادیو Portal Meteor: موسیقی EDMITRY هنگام نبرد.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"‏{0} — رادیو Portal Meteor: موسیقی EDMITRY هنگام نبرد. [ ] — آهنگ.",
"Radio Portal Meteor (EDMITRY): volume":"رادیو Portal Meteor (EDMITRY): صدا",
"Radio: start by itself in battle":"رادیو: در نبرد خودکار روشن شود",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"روبو-نینجا: سایبورگی با کاتانا. در پادگان با پژوهش «پروتکل سایه» باز می‌شود (به کارخانه مکا نیاز دارد). خودش به مناطق دشمن تله‌پورت می‌کند، دشمنان را تکه‌تکه می‌برد (بدون خون — جرقه)، جهش، شوریکن، دوئل با نینجای دشمن. کنترلش کن — حالت خودکار یا کنترل دستی (روی گوشی دکمه‌های مخصوص خودش).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"رادیو Portal Meteor: ۱۰۳ آهنگ از EDMITRY درست داخل بازی. کلید 5 (قابل تغییر)، روی گوشی — ☰ ← تنظیمات ← صدا. صدا و «در نبرد خودکار روشن شود» در تنظیمات؛ موسیقی هنگام انفجارها و صدای بی‌سیم آرام‌تر می‌شود.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"زبان‌های جدید: ازبکی و تاجیکی — کامل؛ چینی، اسپانیایی، پرتغالی — ناقص. انتخاب زبان جدید در منو کنار «مسابقه جدید».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"گوشی: «پنهان کردن نمادها» 👁 دکمه‌های باقی‌مانده را در یک ستون مرتب کنار لبه راست جمع می‌کند؛ حالت عمودی دیگر روی هم نمی‌افتد؛ آیفون — بازی با ژست‌های Safari تداخل ندارد و «اشتراک‌گذاری ← افزودن به صفحه اصلی» آن را تمام‌صفحه اجرا می‌کند.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"از v7.8.1: منوی ☰ گوشه‌ای (توقف، شروع دوباره، آموزش، گرافیک)، بدون Dendy خودکار، دکمه عمل ✋ روی گوشی. v7.8.1 و v7.8 در منوی «🕘 نسخه بازی» باقی ماندند.",
