"Veterans deployed: {0} {1} · lv {2} · battles {3}":"کهنه‌سربازان اعزام‌شده: {0} {1} · سطح {2} · نبرد {3}",
"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"دسته {0} از بین رفت — کهنه‌سربازی‌اش (سطح {1}) از دست رفت. در «دسته‌های من ← شهدا» ببین.",
