"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"هم‌رزمانت کمک می‌خواهند و پاداش می‌دهند، قهرمانان مأموریت می‌دهند، جبهه‌ای که گیر کرده با یک عملیات شکسته می‌شود",
"A request":"درخواست هم‌رزمان",
"Breakthrough":"نقطه عطف نبرد",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"هم‌رزمانت گاهی کمک می‌خواهند: صدا از رادیو، کارت «درخواست» و نشانگر ✋. حوله‌ای زمین‌گیر شده — دشمنان نزدیکش را نابود کن. پاداش: سرباز با کپسول از پایگاه، سلاح از صندوق‌عقب بیابان‌گرد، جایگاه توپچی یا پوشش مداری. نمی‌خواهی — ✕ یا نادیده بگیر.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"دیده‌بان کهنه‌کار «جغد» مأموریتی پیشنهاد می‌دهد. Y — پذیرفتن (N — رد). به نشانگر ★ برو، نگهبانان را بزن و ۳ s کنار خلبان بمان — به دسته‌ات می‌پیوندد.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"جبهه گیر کرده — ستاد نقطه عطف پیشنهاد می‌دهد. Y — پذیرفتن. رله را ۸ s بدون دشمن نزدیک نگه دار: نقشه دشمن ۶۰ s آشکار می‌شود. ژنراتور — برجک‌های دشمن ۲ min خاموش می‌شوند. در استراتژیست — «واگذاری به دسته». دشمن هم همین کار را می‌کند: مراقب ⚠ باش.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"هم‌رزمانت کمک می‌خواهند: کارت «درخواست» و نشانگر ✋. دشمنان نزدیک دسته زمین‌گیرشده را نابود کن — پاداش می‌گیری. ✕ — رد کردن.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"قهرمان «جغد» مأموریتی پیشنهاد می‌دهد — «پذیرفتن» را بزن. به ★ برو، نگهبانان را بزن، کنار خلبان بمان.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"جبهه گیر کرده — «پذیرفتن» را بزن و رله را ۸ s نگه دار: نقشه دشمن یک دقیقه باز می‌شود.",
