"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"تانک اصلی: توپ و مسلسل. «بولداگ» کنسرسیوم محکم‌تر و «عنکبوت» انبوه سریع‌تر است.",
"Heavy tank":"تانک سنگین",
