"Upgrade":"ارتقا",
"Longer, faster jetpacks for all infantry.":"کوله‌پشتی‌های جت دورتر و سریع‌تر برای همهٔ پیاده‌نظام.",
"Extractors mine more ore.":"استخراج‌گرها سنگ‌معدن بیشتری برداشت می‌کنند.",
"Army-wide levels: less damage taken / more damage dealt.":"سطوح برای کل ارتش: آسیب دریافتی کمتر / آسیب واردشده بیشتر.",
"Levels":"سطح‌ها",
"Base":"پایگاه",
