"Produces: ":"تولید می‌کند: ",
"Launch pad":"سکوی پرتاب",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"سیلویی کنار ستاد: کپسول‌ها، صندوق‌های تدارکات و بمب‌افکن‌ها از اینجا از میان پورتال آسمانی به سمت هدف می‌روند. روی آن نمی‌شود ساخت.",
"Economy":"اقتصاد",
"Key building":"ساختمان کلیدی",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"نقطه ضعف — عقب (موتور): آسیب ×{0}. توپ، ۲ برجک مسلسل، پاد موشک؛ خیلی آهسته می‌چرخد — از پهلو دورش بزن.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"نقطه ضعف — هستهٔ درخشان زیر شکم: آسیب از پایین ×{0}. پرتو اعوجاج و کوبش ناحیه‌ای؛ از روی سدها رد می‌شود — فاصله بگیر و دسته‌جمعی نایست.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"در برابرش: بمب‌ها و توپخانه (×{0})، موشک‌ها (×{1})، بمباران گسترده؛ گلوله‌ها تقریباً بی‌اثرند (×{2}).",
"Faction":"جناح",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"ماشین‌های سریع، گله‌های پهپاد، تونل و بازسازی. پیاده‌نظام سبک‌تر ولی سریع‌تر؛ توپ‌ها و ریل‌ها قوی‌تر می‌زنند.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"پیاده‌نظام سنگین با زره نیرودار، سدهای بتنی، تعمیر و توپخانه. کندتر ولی محکم‌تر.",
"Infantry HP":"پیاده‌نظام: استحکام",
"Infantry speed":"پیاده‌نظام: سرعت",
"Jetpacks":"جت‌پک",
"Weapon damage: ":"آسیب سلاح: ",
"Vehicles: ":"ماشین‌ها: ",
"Unique: ":"ویژه: ",
