"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"۲. بازی کن و بلند فکر کن: چه چیزی نامفهوم است، چه چیزی آزاردهنده یا جذاب. گوشهٔ صفحه نسخه، زمان و FPS را نشان می‌دهد — با آن‌ها ضبط با یادداشت‌ها تطبیق داده می‌شود.",
